public class LogSystem {
  private final TreeMap<Long, Integer> map = new TreeMap<>();
  private static final String[] UNITS = {"Year", "Month", "Day", "Hour", "Minute", "Second"};

  public LogSystem() {}

  public void put(int id, String timestamp) {
    map.put(convert(parse(timestamp)), id);
  }

  public List<Integer> retrieve(String s, String e, String granularity) {
    int level = Arrays.asList(UNITS).indexOf(granularity);
    long start = convert(truncate(s, level, false));
    long end = convert(truncate(e, level, true));
    return new ArrayList<>(map.subMap(start, end).values());
  }

  private int[] parse(String timestamp) {
    String[] parts = timestamp.split(":");
    int[] t = new int[6];
    for (int i = 0; i < 6; i++) t[i] = Integer.parseInt(parts[i]);
    return t;
  }

  // keep fields up to the granularity, reset the rest; the end bound is bumped by one unit
  // (exclusive)
  private int[] truncate(String timestamp, int level, boolean upper) {
    int[] t = parse(timestamp);
    for (int i = level + 1; i < 6; i++) t[i] = i <= 2 ? (i == 0 ? 2000 : 1) : 0;
    if (upper) t[level]++;
    return t;
  }

  // 31 days per month and 31 * 12 per year keep the order of timestamps
  private long convert(int[] t) {
    long days = (t[0] - 2000L) * 12 * 31 + (t[1] - 1) * 31L + (t[2] - 1);
    return ((days * 24 + t[3]) * 60 + t[4]) * 60 + t[5];
  }
}
